  "upgrade.trialHistoryNote": "Kung nagbabayad ka para sa Essentials at lilipat sa Business, mananatili ang parehong customer account at kasaysayan ng trial mo. Hindi kasama sa Business ang karagdagang pitong araw na trial. Kung mag-upgrade ka habang tumatakbo pa ang iyong orihinal na trial, hindi mare-reset ang orihinal nitong petsa ng pagtatapos.",
  "upgrade.providerConfirmNote": "Nangangailangan ang mga pagbabago ng plano ng kumpirmasyon mula sa billing provider. Dapat ipakita ang anumang pagkakaiba sa presyo, proration, at petsa ng bisa bago mo aprubahan ang pagbabago. Hindi dapat lumikha ang upgrade ng pangalawang sabay na subscription.",
  "upgrade.chargedThroughProviderNote": "Sisingilin ang mga pagbabago ng plano sa pamamagitan ng billing provider. Maaari mong kanselahin ang iyong subscription mula sa pahinang ito gamit ang button na Kanselahin ang Subscription sa ilalim ng iyong kasalukuyang plano, o mula sa Settings. Ititigil ng pagkansela ang mga susunod na renewal sa katapusan ng iyong bayad na panahon; hindi nito kailanman agad tatapusin ang iyong access. Hindi sinisingil ang mga umiiral na komplimentaryong workspace sa pagtingin sa mga opsyong ito.",
  "billing.cancel.title": "Kanselahin ang subscription",
  "billing.cancel.description": "Mag-unsubscribe mula sa {plan}. Ititigil ng pagkansela ang mga susunod na renewal sa katapusan ng iyong bayad na panahon — hindi nito kailanman agad tatapusin ang iyong access.",
  "billing.cancel.yourPlan": "ang iyong plano",
  "billing.cancel.doneTitle": "Nakansela na ang iyong subscription.",
  "billing.cancel.doneWithEnd": "Mananatili ang iyong buong access hanggang {endDate}. Pagkatapos ng petsang iyon, mayroon kang {graceDays} araw na read-only grace period — maaari ka pa ring mag-log in at makita ang iyong mga produkto, ngunit hindi ka maaaring magdagdag, mag-edit, magbura, mag-scan, mag-import, mag-export o magbago ng anuman. {gracePart}",
  "billing.cancel.graceEndsOn": "Pagkatapos matapos ang 15 araw na grace period sa {date}, permanenteng mabubura ang iyong account at lahat ng impormasyon nito at hindi na mababawi.",
  "billing.cancel.doneNoEnd": "Mananatili ang iyong buong access hanggang sa katapusan ng iyong bayad na panahon. Pagkatapos noon, ilalapat ang 15 araw na read-only grace period. {wipeSentence}",
  "billing.cancel.refundWindowOpen": "Nagkansela ka sa loob ng 3 araw mula sa iyong unang bayad na singil, kaya maaari kang maging kwalipikado para sa refund ng unang bayad na iyon. Hindi mismo nagbibigay ang pagkansela ng refund — hilingin ito sa pamamagitan ng {contact}.",
  "billing.cancel.refundWindowClosed": "Hindi mismo nagbibigay ang pagkansela ng refund. Nalalapat lamang ang mga refund sa loob ng 3 araw mula sa unang matagumpay na bayad na singil, na hinihiling sa pamamagitan ng {contact}.",
  "billing.cancel.notCanceledTitle": "HINDI nakansela ang iyong subscription.",
