  "billing.cancel.alreadyCanceledWithEnd": "Magtatapos ito sa {date}. Mananatili ang iyong buong access hanggang noon. Pagkatapos ng petsang iyon, mayroon kang {graceDays} araw na read-only grace period para makita ang iyong mga produkto. {wipeSentence}",
  "billing.cancel.alreadyCanceledNoEnd": "Magtatapos ito sa katapusan ng kasalukuyang bayad na panahon. Mananatili ang iyong buong access hanggang noon.",
  "billing.cancel.appStoreNote": "Kung mag-subscribe ka kailanman sa pamamagitan ng Google Play o ng Apple App Store, maaaring kailanganin mong kanselahin ito sa pamamagitan ng mga setting ng subscription ng tindahang iyon. Hindi mapipigilan ng dialog na ito ang pagsingil ng app store. Hindi kinakansela ng pag-uninstall ng app o pagbura ng iyong StockHaven account ang subscription sa tindahan.",
  "billing.cancel.trialNote": "Ang pagkansela sa panahon ng iyong trial ay magpapanatili ng iyong buong 7 araw — magtatapos ang access sa {date}, at hindi ka sisingilin.",
  "billing.cancel.trialNoteNoDate": "Ang pagkansela sa panahon ng iyong trial ay magpapanatili ng iyong buong 7 araw, at hindi ka sisingilin.",
