  "billing.cancel.gracePeriodTitle": "Pagkatapos ng petsang iyon, isang {graceDays} araw na read-only grace period.",
  "billing.cancel.gracePeriodRest": "Maaari ka pa ring mag-log in at makita ang iyong mga produkto, kaya maaari mong tingnan kung ano ang mayroon ka at isulat ito. Lahat ng iba pa ay naka-block: walang pagdaragdag, pag-edit, pagbura, pag-scan, pag-import, pag-export o paglipat, walang settings, walang staff.",
