  "billing.readiness.body": "Suriin ang aktwal na mga rekord ng subscription at trial nang hindi bumibili ng anuman. Mananatiling hindi nababago ang iyong komplimentaryong Business account at ang iyong sample na pajama. Hindi nito binubuksan ang Stripe checkout, hindi naniningil sa card, o hindi binabago ang plano.",
