  "billing.dryRun.title": "Essentials → Business — simulasyon para sa pagsasanay",
  "billing.dryRun.body": "Magsanay sa mga iminungkahing panuntunan sa pag-upgrade gamit ang ganap na kathang-isip na mga rekord sa browser na ito. Hindi nito binabasa o binabago ang iyong tunay na TEST — sample ng Pajama Pants, ang iyong kasalukuyang Business workspace, Stripe, mga trial, subscription o imbentaryo.",
  "billing.dryRun.runButton": "Patakbuhin ang lokal na simulasyon ng upgrade (walang singil)",
