  "billing.dryRun.preserved": "Napanatili ang parehong subscription, napanatili ang isang orihinal na trial, at hindi nabago ang kunwaring imbentaryo ng pajama. Mananatili sa Essentials ang halimbawang customer hanggang ang tunay, nakumpirma ng provider na bayad na renewal ay magbigay-katwiran sa pagbabago ng access.",
  "billing.dryRun.limitations": "Hindi sinusubok ng lokal na simulasyon ang mga pagbabago ng subscription sa Stripe, bayad, webhook, quote na kasama ang buwis, live na subscription o ang iyong aktwal na mga rekord ng negosyo.",
