  "exports.eyebrow": "Data",
  "exports.title": "Mga export at backup",
  "exports.subtitleStart": "Palaging limitado ang mga download sa",
  "exports.subtitleRest": ". May label sa bawat file ng pangalan ng negosyo at ng petsa kung kailan ito ginawa.",
  "exports.createBusinessFirst": "Gumawa muna ng negosyo — ang mga export ay pag-aari ng isang negosyo, hindi ng app.",
  "exports.lockedTitle": "Ang mga export na CSV at Excel ay feature ng Business",
  "exports.lockedDesc": "Nasa planong Essentials ang iyong workspace. Nagdaragdag ang Business ng mga export na CSV at Excel, valuation ng stock, walang limitasyong produkto at staff, mga supplier, purchasing at mga bundle.",
  "exports.seeBusiness": "Tingnan kung ano ang kasama sa Business",
  "exports.whatTheseAre": "Ano ang mga file na ito",
  "exports.about1": "Ang bawat dataset ay dumarating bilang CSV o totoong Excel workbook (.xlsx) — ang buong workbook ng imbentaryo ay Excel lamang, na may isang sheet bawat dataset. Nagbubukas ang mga CSV file sa Excel, Numbers, Google Sheets at karamihan ng mga stock app. Napapanatili ang tekstong UTF-8, mga kuwit na naka-quote, mga line break sa mga tala at mga nangungunang zero sa mga code, at nino-neutralize ang mga cell na nagsisimulang parang formula kaya binubuksan ng spreadsheet ang mga ito bilang teksto.",
  "exports.about2": "Sa mga Excel file, ang mga SKU, UPC, ISBN at barcode ay mga text cell — hindi kailanman scientific notation at hindi kailanman tinatanggalan ng zero — na may inilapat na lapad ng column, mga filter sa header at mga format ng pera o dami. Pinapanatili ng buong workbook ng imbentaryo ang mga produkto, antas ng stock, lokasyon at paggalaw sa magkakahiwalay na sheet.",
  "exports.about3": "Humihinto ang napakalalaking export sa 20,000 hilera bawat dataset — kapag nangyari iyon, sinasabi ito ng pangalan ng file (truncated-20000), kaya hindi kailanman magpapanggap na kumpleto ang isang bahagyang file.",
  "exports.about4": "Ang backup ay snapshot ng iyong data, hindi one-click na restore. Manu-mano at review-muna ang pag-restore nito, kaya ingatan ang file — wala pa sa app ang makakabuo muli ng tinanggal na negosyo mula rito. Hiwalay na hinahawakan ang mga backup ng code ng app at ng platform na Base44 mula sa mga file na ito.",
  "exports.about5": "Nakalista ang mga larawan at attachment bilang kanilang mga nakaimbak na link — hindi isinasama sa download ang mismong mga image file.",
  "exports.backupTitle": "Buong backup",
  "exports.backupDesc": "Isang file na may mga produkto, lokasyon, antas ng stock, kumpletong ledger ng paggalaw, mga supplier, purchasing, order, return, count at listing ng negosyong ito — pati ang mga setting ng profile nito. Itago ito sa lugar na kontrolado mo.",
  "exports.backupIncludes1": "Mga produkto, code, gastos at tala",
  "exports.backupIncludes2": "Mga lokasyon at dami bawat lokasyon",
  "exports.backupIncludes3": "Bawat paggalaw, kasama ang gumawa at oras",
  "exports.backupIncludes4": "Purchasing, mga order, return at count",
