  "import.eyebrow": "Data",
  "import.title": "Sentro ng pag-import",
  "import.subtitleStart": "Tatlong magkakahiwalay na operasyon sa spreadsheet, kaya hindi kailanman darating ang pagwawasto ng presyo bilang resibo ng stock. Lahat ay napupunta sa",
  "import.subtitleRest": " lamang, at walang isinusulat hangga't hindi pumapasa ang dry run.",
  "import.createBusinessFirst": "Gumawa muna ng negosyo — ang mga in-import na produkto ay pag-aari ng isang negosyo.",
  "import.createBusinessFirstShort": "Gumawa muna ng negosyo.",
  "import.whatEachDoes": "Ano ang ginagawa ng bawat operasyon",
  "import.createTitle": "Gumawa ng mga bagong produkto",
  "import.createDesc": "nagdaragdag ng mga hilerang wala pa sa catalog. Nilalaktawan ang mga duplicate na SKU at barcode na ginagamit na, at maaaring mapunta ang panimulang stock sa lokasyong pipiliin mo bilang resibo.",
  "import.updateTitle": "I-update ang mga umiiral na produkto",
  "import.updateDesc": "itinutugma ang bawat hilera ayon sa SKU o record ID at ipinapakita ang lumang halaga katabi ng iminumungkahing bagong halaga. Hindi ginagalaw ng mga blangkong cell ang naka-save na halaga maliban kung hihilingin mong i-clear ang mga blangko, at hindi kailanman ginagalaw ang mga dami.",
  "import.receiveModeTitle": "Tumanggap ng stock",
  "import.receiveModeDesc": "nagdaragdag ng mga dumarating na dami sa isang lokasyon at nagsusulat ng resibo sa ledger ng paggalaw para sa bawat linya. Minamarkahan ang bawat batch, kaya hindi matatanggap nang dalawang beses ang parehong sheet.",
  "import.excelNote": "Direktang binabasa ang mga Excel workbook (.xlsx) — piliin ang worksheet at itutugma ang mga column para sa iyo. Mananatiling buo ang mga code: ang UPC na naka-save bilang teksto ay pinapanatili ang mga digit at nangungunang zero nito. Ang mga hilerang hindi ma-import ay nakalista kasama ang dahilan",
