  "valuation.noRetailPrice": "walang retail price",
  "valuation.footnote": "Ginagamit ng halaga ng gastos ang kasalukuyang gastos bawat yunit ng bawat produkto, kaya ang pagtanggap sa bagong presyo ay muling nagpapahalaga sa buong istante. Binibilang pa rin dito ang mga nakahandang yunit — nasa kamay ang mga ito, ipinangako lamang sa isang order. Hindi kailanman itinuturing na zero ang nawawalang pera; iwanang blangko ang field hangga't hindi nalalaman ang numero.",
