  "print.templateIsBusiness": "Ang {label} ay feature ng Business",
  "print.supplierBlockedDesc": "Ang mga dokumento ng supplier ay kasama ng planong Business — mga supplier, purchasing at purchase order. Patuloy na gagana ang lahat ng mayroon ka ngayon.",
  "print.seeBusiness": "Tingnan kung ano ang kasama sa Business",
  "print.nothingToPrint": "Wala pang mai-print",
  "print.pickOrderHint": "Pumili ng purchase order mula sa listahan para makita ang preview ng dokumento.",
  "print.pickCustomerOrderHint": "Pumili ng order ng customer mula sa listahan para makita ang preview ng dokumento.",
  "print.pickReturnHint": "Pumili ng naka-log na return mula sa listahan para makita ang preview ng dokumento.",
  "print.chooseStyleHint": "Pumili ng estilo, pagkatapos ay pumili ng mga produkto mula sa listahan. Ipinapakita ng preview nang eksakto kung ano ang lalabas sa printer.",
  "print.howToReach": "Paano maabot ang iyong printer",
  "print.howIntro": "Kumokonekta ang app na ito sa mga printer na pag-aari mo na — hindi ito mismo isang printer. May apat na paraan para maabot ang isa, at nagpi-print ang mga label sa parehong plano sa alinman sa mga ito. Ang mga packing slip, purchase order, dokumento ng supplier at ulat ay Business lamang, anuman ang koneksyon.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "Mula sa pahinang ito, sa desktop na Chrome o Edge at sa Android Chrome: piliin ang iyong label printer at direktang mapupunta rito ang mga label. Hindi ito gumagana sa iOS Safari — sa iPhone, kasama ng mobile app ang pag-print sa Bluetooth. Ang printer na Zebra ZPL lamang o sariling wika ng Brother ang ginagamit ay hindi maiintindihan ang mga label na ipinapadala ng pahinang ito; sinusuri iyon laban sa mga totoong printer bago ito sabihing gumagana.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "I-install ang printer sa Wi-Fi ng iyong shop, pagkatapos ay gamitin ang button na I-print — nagpi-print ito sa pamamagitan ng printer na naka-install sa computer na ito, sa network ng shop. Sa iPhone, built-in ang AirPrint: ang AirPrint printer na nasa parehong Wi-Fi ay lilitaw lamang sa print sheet, walang cord at walang app na kailangan, at hindi kailangan ng app ng code na partikular sa AirPrint. Dapat suportahan ng printer ang AirPrint (ginagawa ito ng karamihan ng mga bago) at dapat nasa parehong Wi-Fi ang telepono at printer.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Ikonekta ang printer sa network ng iyong shop gamit ang Ethernet cord, i-install ito sa computer, at mag-print sa pamamagitan ng button na I-print. Ang Ethernet ay landas para sa desktop at computer — hindi gumagamit ng mga Ethernet cord ang mga iPhone.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "Ikabit ang printer sa computer gamit ang cord nito at gamitin ang button na I-print — nagpi-print ito sa pamamagitan ng printer na naka-install doon. Sa Android phone na may USB OTG cable, direktang nakikipag-usap sa printer ang button na USB sa itaas. Hindi maaaring mag-print ang mga iPhone sa USB nang direkta — walang WebUSB doon — kaya gamitin ang Wi-Fi / AirPrint, o Bluetooth mula sa mobile app.",
  "print.howCordsLead": "Nakakatulong pa rin ang mga cord sa mga iPhone, isang hakbang ang layo.",
  "print.howCordsBody": "Ang USB printer na nakakabit sa computer ng shop, o Ethernet printer na nakakonekta sa network, ay lumilitaw sa iyong iPhone sa Wi-Fi ng shop (AirPrint / shared printer) — inilalagay ng mga cord ang printer sa network nang matatag, at inaabot ito ng telepono nang wireless.",
  "print.howOfflineLead": "Kung mawala ang internet,",
  "print.howOfflineBody": "nagpi-print pa rin ang mga label at dokumentong nasa pahinang ito na — hindi kailangan ng koneksyon ng button na I-print, ng PDF ng mga label, ng Bluetooth at ng USB. Ang kailangan ng internet ay ang pag-load ng pahina at ng mga produkto nito sa simula pa lang. Ang buong offline mode (paggana sa app nang walang koneksyon) ay hiwalay at mas malaking gawain at hindi inaangkin dito.",
