  "settings.cancelSubscription": "Kanselahin ang Subscription",
  "settings.cancelTerms.appleLink": "Mga tagubilin sa pagkansela sa Apple",
  "settings.cancelTerms.googlePlayLink": "Mga tagubilin sa pagkansela sa Google Play",
  "settings.cancelTerms.graceTitle": "Pagkatapos matapos ang iyong bayad na panahon — 15 araw na palugit, pagkatapos ay pagbura:",
  "settings.cancelTerms.intro": "Ito ang mga tuntunin para sa mga bayad na subscription sa Luminous StockHaven. Ang pagsingil sa subscription sa website ay sa pamamagitan ng Stripe. Maaari mong kanselahin ang iyong subscription anumang oras gamit ang button na Kanselahin ang Subscription sa ibaba — hindi kailangan ng pag-apruba ng tauhan. Maaari ring asikasuhin ang mga kahilingan sa pagkansela at refund sa pamamagitan ng opisyal na contact sa suporta sa customer, theluminousbookshop@outlook.com.",
  "settings.cancelTerms.noApprovalBody": "Maaari mong kanselahin ang iyong subscription anumang oras. Hindi kailangan ng pag-apruba ng tauhan. Hihinto lamang ang mga susunod na renewal pagkatapos kumpirmahin ng provider ng pagsingil ang pagkansela.",
  "settings.cancelTerms.noApprovalTitle": "Kanselahin nang walang pag-apruba:",
  "settings.cancelTerms.paymentBody": "Para sa mga bayad na trial, ang pitong araw na trial ay nangangailangan ng paraan ng pagbabayad sa pag-sign up. Maliban kung kanselahin sa loob ng naaangkop na deadline sa pagkansela ng trial, awtomatikong sisingilin ang napiling buwanang plano pagkatapos ng trial. Dapat ipakita sa pag-sign up ang presyo, unang petsa ng pagsingil, at deadline sa pagkansela na partikular sa provider. Ang pagsingil sa trial ay sa pamamagitan ng Stripe.",
  "settings.cancelTerms.paymentTitle": "Paraan ng pagbabayad at awtomatikong renewal:",
  "settings.cancelTerms.remainingBody": "Kung nakapagbayad ka na para sa isang panahon ng pagsingil, maaari mong panatilihin ang access hanggang sa nabanggit na nabayarang petsa. Ang mas maagang pagtatapos ay nangangailangan ng angkop na kumpirmasyon ng provider at anumang naaangkop na pag-asikaso ng refund. Nagtatapos ang access sa libreng trial ayon sa petsa ng pagtatapos ng trial na kinumpirma ng provider.",
  "settings.cancelTerms.remainingTitle": "Natitirang access:",
  "settings.cancelTerms.storesBody": "Kung mag-subscribe ka sa pamamagitan ng Google Play o Apple App Store, ang iyong subscription ay sisingilin at pamamahalaan ng tindahang iyon. Maaaring kailanganin mong kanselahin ito nang direkta sa seksyon ng mga subscription ng parehong Google o Apple account na ginamit sa pag-subscribe. Ang pagkansela ng hiwalay na subscription sa website, pag-uninstall ng app na ito, o paghiling ng pagbura ng account sa Luminous StockHaven ay hindi awtomatikong nagkakansela ng subscription na sinisingil ng tindahan. Tingnan ang iyong resibo ng pagbili upang kumpirmahin kung sino ang naniningil sa iyo.",
  "settings.cancelTerms.storesTitle": "Mga subscription sa Google Play at Apple App Store (kung mag-subscribe ka sa pamamagitan ng tindahan):",
  "settings.cancelTerms.title": "Mga Tuntunin at Kundisyon sa Pagkansela",
  "settings.cancelTerms.trialBody": "Ang pitong araw na trial ay maaari lamang gamitin nang isang beses bawat karapat-dapat na customer. Ang pagkansela ng trial o subscription ay hindi nagbibigay ng isa pang trial; dapat pumili ang mga bumabalik na customer ng bayad na subscription.",
  "settings.cancelTerms.trialTitle": "Isang libreng trial:",
  "settings.canceled.endsOn": "Nakansela ang subscription na ito at magtatapos sa {date}. Mananatili ang iyong buong access hanggang noon.",
  "settings.delete.checking": "Sinusuri kung may kasalukuyang kahilingan sa pagbura…",
  "settings.delete.description": "Hilingin ang pag-alis ng iyong sign-in account sa Luminous StockHaven.",
  "settings.delete.dialogDescription": "Humihiling ito ng pagsusuri ng pagbura ng account. Hindi nito agad inaalis ang iyong login o imbentaryo, at hindi nito kinakansela ang anumang subscription sa Stripe. I-type ang {word} upang kumpirmahing gusto mong isumite ang kahilingan.",
  "settings.delete.dialogTitle": "Hilingin ang Pagbura ng Account",
  "settings.delete.enterDelete": "Ilagay ang {word} upang kumpirmahin",
  "settings.delete.exportFirst": "I-export muna ang iyong imbentaryo kung kailangan mong itago ang iyong mga rekord.",
  "settings.delete.intro": "Ang pagsusumite ng kahilingan ay hindi agad nagbubura ng iyong account, mga negosyo, o imbentaryo. Hiwalay na sinusuri ang mga kahilingan bago makumpleto ang pagbura. Ang kahilingang ito ay hindi nagkakansela ng subscription sa Stripe o humihinto ng susunod na pagsingil; dapat hiwalay na asikasuhin ang pagkansela ng subscription sa pamamagitan ng provider ng pagsingil.",
