  "settings.separateDecisions": "Magkahiwalay na desisyon ang pagkansela ng subscription at pagbura ng account. Walang subscription na kakanselahin o account na buburahin sa pagtingin sa mga tuntuning ito.",
  "settings.software.application": "Aplikasyon",
  "settings.software.description": "Ang Luminous StockHaven ay ang aplikasyon. Ang mga detalye ng iyong negosyo sa ibang bahagi ng pahinang ito ay sa iyo.",
  "settings.software.fixedNote": "Nakapirmi ang mga halagang ito at pareho ang hitsura para sa bawat negosyo. Ang pagpapalit ng pangalan ng iyong negosyo o ng logo nito ay hindi kailanman nagbabago ng pangalan ng aplikasyon.",
