  "settings.trial.cancelKeeps": "Ang pagkansela sa panahon ng iyong trial ay nagpapanatili ng iyong buong 7 araw — magtatapos ang access sa {date}, at hindi ka sisingilin.",
  "staff.access.noSeatBody": "Walang upuan ng tauhan ang iyong account para sa negosyong ito, kaya nananatiling sarado ang stock nito. Hilingin sa may-ari na idagdag ka sa Mga tauhan at tungkulin.",
  "staff.access.noSeatTitle": "Hindi bukas ang negosyong ito sa iyong login",
  "staff.access.pendingBody": "May imbitasyon ang negosyong ito para sa iyong email na hindi pa naa-activate. Hilingin sa may-ari na itakda ang katayuan ng iyong tauhan sa aktibo. Walang makikita dito hanggang noon.",
  "staff.access.pendingTitle": "Hindi pa aktibo ang iyong imbitasyon",
  "staff.access.signOut": "Mag-sign out",
  "staff.access.suspendedBody": "Sinuspinde ng isang administrator ang account ng tauhan na ito para sa aktibong negosyo. Hilingin sa kanila na ibalik ka sa aktibo, pagkatapos ay mag-sign in muli.",
  "staff.access.suspendedTitle": "Naka-pause ang iyong access",
  "staff.addFirst": "Idagdag ang unang miyembro ng tauhan",
  "staff.addMember": "Magdagdag ng miyembro ng tauhan",
  "staff.emptyBody": "Magdagdag ng tao, bigyan sila ng tungkulin at mga pahintulot na kasama nito, at iimbitahan sila sa pamamagitan ng email na mag-sign in sa negosyong ito.",
  "staff.emptyTitle": "Wala pang tauhan",
  "staff.eyebrow": "Koponan",
  "staff.how.p1": "Ang bawat miyembro ay may tungkulin at sarili nilang listahan ng pahintulot, kaya maaari kang magsimula mula sa isang tungkulin at baguhin ang isang bagay nang hindi gumagawa ng bagong tungkulin. Ang pag-edit ng tungkulin ay hindi muling isinusulat ang mga miyembrong nasa loob na nito — buksan ang isang miyembro upang muling ilapat ang mga default ng kanilang tungkulin.",
  "staff.how.p2": "Ang mga pasadyang tungkulin ay feature ng Business: ginagamit ng Essentials ang limang built-in na tungkulin (Owner, Manager, Stock clerk, Sales clerk, Viewer).",
  "staff.how.p3": "Ipinapadala ang mga imbitasyon sa pamamagitan ng email. Maaari lamang mag-sign in ang isang miyembro kapag tinanggap nila ito, at ang pag-alis ng isang tao mula sa listahang ito ay hindi nagbubura ng kanilang account sa app.",
  "staff.how.p4": "Ang tindahan ay ang lokasyong itinalaga sa isang tao. Nakatala ito sa kanilang card; ang maaari nilang buksan ay pinagpapasyahan pa rin ng kanilang tungkulin at mga pahintulot.",
  "staff.how.p5": "Pinagpapasyahan ng mga pahintulot kung ano ang maaaring buksan ng bawat tao: nakatago ang mga item sa menu na nasa labas ng kanilang tungkulin, at ang naka-block na address ay nagpapakita ng abisong “wala sa iyong tungkulin” sa halip na ang pahina. Nalalapat ang pagbabago sa susunod na pag-load ng taong iyon ng app; ang pagsuspinde sa isang miyembro ay ganap na nagla-lock sa kanila.",
  "staff.how.p6": "Makikita at mababago ng mga administrator ang lahat ng data, mapapamahalaan ang mga user at tungkulin ng app, at hindi kailanman nililimitahan ng tungkulin ng tauhan. Ang isang taong walang rekord ng tauhan — ang may-ari ng bagong negosyo — ay nananatiling may buong access.",
  "staff.howTitle": "Paano gumagana ang mga tauhan at tungkulin",
