  "payroll.dd.steps.body": "1. Kailangan mo ng business bank account na makakapagpadala ng mga bayad na ACH. 2. Kolektahin ang nilagdaang form ng pahintulot mula sa bawat miyembro ng team — nakakatulong ang voided check para ma-verify ang mga numero. 3. Ipadala ang payroll 2-3 araw ng negosyo bago ang araw ng sahod para dumating ang pera sa oras. 4. Karamihan ng mga estado ay nangangailangan ng nakasulat na pahintulot ng miyembro ng team. Kinokolekta ng app na ito ang mga form at ginagabayan ka sa mga hakbang — ang aktwal na pagpapadala ng pera ay nangyayari sa pamamagitan ng sarili mong bangko.",
