  "training.newForYou": "Bagong pagsasanay para sa iyo",
  "training.newForYouHelp": "Idinagdag ang mga araling ito dahil lumaki ang iyong tungkulin, o may nag-assign sa iyo ng mga ito. Tapusin sila para matutunan ang mga bagong bahagi ng app.",
