  "rewards.subtitle": "Magpasalamat gamit ang isang reward — isang porsiyentong diskwento, isang gift card, o anumang ilalarawan mo.",
  "rewards.title": "Mga reward at insentibo",
  "rewards.value.giftCard": "{value} gift card",
