  "workforce.tab.rewards": "Mga Reward",
  "training.lessons.mgr-give-rewards.step1": "Buksan ang Workforce at i-tap ang Mga Reward. Piliin ang miyembro ng team, pagkatapos ang uri: isang porsiyentong diskwento sa tindahan, isang gift card, o iba pang ilalarawan mo sa sarili mong mga salita.",
  "training.lessons.mgr-give-rewards.step2": "Bigyan ang reward ng maikling pangalan at isang tala kung gusto mo. Makakatanggap agad ang tao ng kampana, at maghihintay ang reward sa kanilang Aking mga reward kasama ang sarili nitong code.",
  "training.lessons.mgr-give-rewards.step3": "Ang hangganan, ayon sa disenyo: staff LAMANG ang bibigyan mo ng reward. Hindi mo maaaring bigyan ng reward ang iyong sarili o ang ibang manager — ang pagbibigay ng reward sa isang manager ay desisyon ng may-ari, at tatanggihan ito ng app nang malinaw.",
  "training.lessons.mgr-give-rewards.step4": "Sa till, i-type ang code na ipinapakita sa iyo ng miyembro ng team at markahan itong nagamit — bawat code ay gumagana nang isang beses. Maaari mong gawing walang bisa ang isang reward na ibinigay mo kung magbago ang mga plano; ang mga regalo ng may-ari ay sa may-ari na gawing walang bisa.",
  "training.lessons.mgr-give-rewards.title": "Pagbibigay ng mga reward sa iyong staff",
  "training.lessons.owner-give-rewards.step1": "Ang mga reward ay nasa Workforce, sa tab na Mga Reward, at para lamang sila sa planong Business — sa Essentials ipinapakita ng tab ang isang naka-lock na pinto, para makita ng iyong team kung ano ang hawak ng mas malaking plano.",
  "training.lessons.owner-give-rewards.step2": "Maaari mong bigyan ng reward ang SINUMAN sa team — staff at mga manager. Piliin ang tao, pagkatapos ang uri: isang porsiyentong diskwento sa tindahan (anumang porsiyentong pipiliin mo), isang gift card sa kahit saan, o anumang insentibong ilalarawan mo sa sarili mong mga salita.",
  "training.lessons.owner-give-rewards.step3": "Mapupunta ang reward kasama ang sarili nitong one-time na code at tutunog sa kampana ng tao. Ipapakita nila ang code sa till; i-type ito ng isang may-ari o manager para markahan itong nagamit.",
  "training.lessons.owner-give-rewards.step4": "Ang isang naka-print o ibinahaging slip ng reward ay nagdadala lamang ng pangalan ng IYONG negosyo — hindi kailanman ng app. Pasasalamat ito ng iyong tindahan, hindi isang patalastas.",
  "training.lessons.owner-give-rewards.title": "Pagbibigay ng mga reward (planong Business)",
  "training.lessons.owner-rewards-oversight.step1": "Maaari ring magbigay ng mga reward ang iyong manager — sa staff lamang. Tinatanggihan ng app ang isang manager na binibigyan ng reward ang kanilang sarili o ang ibang manager; ang pagbibigay ng reward sa isang manager ay palaging desisyon mo.",
  "training.lessons.owner-rewards-oversight.step2": "Makikita mo ang bawat reward sa negosyo sa Kasaysayan ng mga reward: kung sino ang nagbigay nito, kung sino ang nakakuha nito, at kung handa na ito, nagamit o walang bisa. Makikita lamang ng isang manager ang mga reward na ibinigay nila at ang mga natanggap nila.",
  "training.lessons.owner-rewards-oversight.step3": "Maaari mong gawing walang bisa ang anumang reward, kasama ang ibinigay ng iyong manager. Maaaring gawing walang bisa ng isang manager ang sarili nilang mga regalo, ngunit hindi kailanman ang sa iyo.",
  "training.lessons.owner-rewards-oversight.step4": "Bawat code ay gumagana nang eksaktong isang beses, at ang isang reward na walang bisa ay hindi na kailanman magagamit — palaging ipinapakita ng kasaysayan kung paano natapos ang isang reward.",
  "training.lessons.owner-rewards-oversight.title": "Pangangasiwa sa mga reward: ang pagbibigay ng iyong manager",
  "training.lessons.staff-your-rewards.step1": "Kapag binigyan ka ng iyong manager o ng may-ari ng reward, tutunog ang iyong kampana. Buksan ang Workforce at i-tap ang Mga Reward para makita ito sa ilalim ng Aking mga reward.",
  "training.lessons.staff-your-rewards.step2": "Bawat reward ay may sarili nitong code. Itago ito sa iyong sarili — kung sino ang magpapakita ng code sa till ay siya ang gagamit ng reward.",
  "training.lessons.staff-your-rewards.step3": "Para gamitin ito, ipakita ang code kapag bumibili ka. I-type ito ng tao sa till at markahan itong nagamit — bawat code ay gumagana nang eksaktong isang beses.",
  "training.lessons.staff-your-rewards.step4": "Ang mga reward ay isang treat ng planong Business. Kung wala sa Business ang iyong tindahan, ipinapakita ng tab na Mga Reward ang isang naka-lock na pinto sa halip — iyon ang plano, hindi isang pagkakamali.",
  "training.lessons.staff-your-rewards.title": "Ang iyong mga reward: paghahanap ng iyong code at paggamit nito",
