  "pos.events.heldPlanNote": "Ang ilang benta sa ibaba ay dumating habang wala sa planong Business ang tindahang ito. Iniingatan silang ligtas at walang nabilang. Ngayong nasa Business na ang tindahan, maaari mo na silang bilangin.",
